import React, { useState, useEffect, useRef } from 'react';
import { useStore } from '../../store/useStore';
import { apiGet } from '../../utils/api';

export default function VivaJoin() {
  var store = useStore();
  var [phase, setPhase] = useState('join');
  var [roomId, setRoomId] = useState('');
  var [invites, setInvites] = useState([]);
  var [session, setSession] = useState(null);
  var [camOk, setCamOk] = useState(false);
  var [micOk, setMicOk] = useState(false);
  var [permError, setPermError] = useState('');
  var [camOn, setCamOn] = useState(true);
  var [micOn, setMicOn] = useState(true);
  var [awayTime, setAwayTime] = useState(null);
  var [awayCountdown, setAwayCountdown] = useState(600);
  var previewRef = useRef(null);
  var selfVidRef = useRef(null);
  var streamRef = useRef(null);

  useEffect(function() { loadInvites(); }, []); // eslint-disable-line

  function loadInvites() {
    store.loadNotifications().then(function(notifs) {
      var vivaInvites = notifs.filter(function(n) { return n.viva_room_id; });
      setInvites(vivaInvites);
    });
  }

  async function handleJoin(id) {
    var vid = id || roomId;
    if (!vid) return;
    try {
      var s = await apiGet('/viva/' + vid);
      setSession(s);
      setRoomId(vid);
      setPhase('permission');
    } catch (e) { alert('Room not found: ' + e.message); }
  }

  async function requestPermissions() {
    setPermError('');
    try {
      var stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: true });
      streamRef.current = stream;
      setCamOk(true);
      setMicOk(true);
      var attempts = 0;
      var interval = setInterval(function() {
        if (previewRef.current) { previewRef.current.srcObject = stream; clearInterval(interval); }
        attempts++;
        if (attempts > 20) clearInterval(interval);
      }, 200);
    } catch (e) {
      setPermError('Camera/Mic access denied. Please allow access in browser settings and try again.');
      if (e.name === 'NotAllowedError') {
        setPermError('Permission denied. Click the camera icon in your browser address bar to allow access, then refresh.');
      }
    }
  }

  function enterRoom() {
    setPhase('room');
    setTimeout(function() {
      if (selfVidRef.current && streamRef.current) {
        selfVidRef.current.srcObject = streamRef.current;
      }
    }, 300);
  }

  function toggleCam() {
    if (streamRef.current) {
      streamRef.current.getVideoTracks().forEach(function(t) { t.enabled = !camOn; });
      setCamOn(!camOn);
    }
  }

  function toggleMic() {
    if (streamRef.current) {
      streamRef.current.getAudioTracks().forEach(function(t) { t.enabled = !micOn; });
      setMicOn(!micOn);
    }
  }

  // Away detection
  useEffect(function() {
    if (phase !== 'room') return;
    function handleAway() {
      if (document.hidden) {
        setAwayTime(Date.now());
        localStorage.setItem('viva_away', JSON.stringify({ viva_id: roomId, since: Date.now() }));
      }
    }
    document.addEventListener('visibilitychange', handleAway);
    window.addEventListener('blur', handleAway);
    return function() {
      document.removeEventListener('visibilitychange', handleAway);
      window.removeEventListener('blur', handleAway);
    };
  }, [phase, roomId]);

  useEffect(function() {
    if (!awayTime) return;
    var timer = setInterval(function() {
      var elapsed = Math.floor((Date.now() - awayTime) / 1000);
      var remaining = 600 - elapsed;
      if (remaining <= 0) {
        clearInterval(timer);
        if (streamRef.current) streamRef.current.getTracks().forEach(function(t) { t.stop(); });
        setPhase('join');
        alert('Session ended due to inactivity');
      } else {
        setAwayCountdown(remaining);
      }
    }, 1000);
    return function() { clearInterval(timer); };
  }, [awayTime]);

  function returnFromAway() {
    setAwayTime(null);
    setAwayCountdown(600);
    localStorage.removeItem('viva_away');
  }

  // Away countdown screen
  if (awayTime && phase === 'room') {
    var mins = Math.floor(awayCountdown / 60);
    var secs = awayCountdown % 60;
    return (
      <div style={{ minHeight: 'calc(100vh - 60px)', display: 'flex', alignItems: 'center', justifyContent: 'center', flexDirection: 'column', background: '#0d0d14' }}>
        <div style={{ fontSize: '3rem', marginBottom: 16 }}>⏸</div>
        <h2 style={{ color: '#fff', marginBottom: 8 }}>You left the Viva Room</h2>
        <div style={{ fontSize: '2.5rem', fontWeight: 800, color: 'var(--warning)', fontFamily: 'JetBrains Mono, monospace' }}>
          {String(mins).padStart(2, '0')}:{String(secs).padStart(2, '0')}
        </div>
        <div style={{ color: '#9ca3af', marginTop: 8, marginBottom: 24 }}>Return before the timer runs out</div>
        <button className="btn btn-primary btn-lg" onClick={returnFromAway}>▶ Return to Viva</button>
      </div>
    );
  }

  // Join phase
  if (phase === 'join') {
    return (
      <div className="fade-up">
        <div className="page-title" style={{ marginBottom: 24 }}>🎙 Viva Voce</div>
        {invites.length > 0 && (
          <div style={{ marginBottom: 24 }}>
            <div style={{ fontWeight: 600, marginBottom: 12, display: 'flex', alignItems: 'center', gap: 8 }}>
              📬 Viva Invitations
              <button className="btn btn-ghost btn-sm" onClick={loadInvites}>↻ Refresh</button>
            </div>
            <div className="grid-2">
              {invites.map(function(inv) {
                return (
                  <div key={inv.notification_id} className="card" style={{ borderLeft: '4px solid var(--accent)' }}>
                    <div style={{ fontWeight: 600, marginBottom: 4 }}>{inv.title}</div>
                    <div style={{ fontSize: '0.85rem', color: 'var(--text3)', marginBottom: 12 }}>{inv.message}</div>
                    <button className="btn btn-primary btn-sm" onClick={function() { handleJoin(inv.viva_room_id); }}>🚀 Join Now</button>
                  </div>
                );
              })}
            </div>
          </div>
        )}
        <div className="card" style={{ maxWidth: 480 }}>
          <div className="card-title">Join by Room ID</div>
          <div style={{ display: 'flex', gap: 8, marginTop: 12 }}>
            <input className="form-input" value={roomId} onChange={function(e) { setRoomId(e.target.value); }} placeholder="Enter Room ID" style={{ flex: 1 }} />
            <button className="btn btn-primary" onClick={function() { handleJoin(); }} disabled={!roomId}>Join</button>
          </div>
        </div>
      </div>
    );
  }

  // Permission phase
  if (phase === 'permission') {
    return (
      <div className="fade-up" style={{ maxWidth: 500, margin: '40px auto', textAlign: 'center' }}>
        <div style={{ fontSize: '3rem', marginBottom: 12 }}>🎥</div>
        <h2 style={{ marginBottom: 4 }}>Camera & Microphone Access</h2>
        <div style={{ color: 'var(--text3)', marginBottom: 24 }}>Required for the viva session</div>
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12, marginBottom: 20 }}>
          <div className="card" style={{ textAlign: 'center', padding: 20 }}>
            <div style={{ fontSize: '1.5rem', marginBottom: 8 }}>{camOk ? '✅' : '📷'}</div>
            <div style={{ fontWeight: 600 }}>Camera</div>
            <div style={{ fontSize: '0.8rem', color: camOk ? 'var(--success)' : 'var(--text3)' }}>{camOk ? 'Ready' : 'Pending'}</div>
          </div>
          <div className="card" style={{ textAlign: 'center', padding: 20 }}>
            <div style={{ fontSize: '1.5rem', marginBottom: 8 }}>{micOk ? '✅' : '🎤'}</div>
            <div style={{ fontWeight: 600 }}>Microphone</div>
            <div style={{ fontSize: '0.8rem', color: micOk ? 'var(--success)' : 'var(--text3)' }}>{micOk ? 'Ready' : 'Pending'}</div>
          </div>
        </div>
        {camOk && <div style={{ marginBottom: 16 }}><video ref={previewRef} autoPlay muted playsInline style={{ width: '100%', maxWidth: 320, borderRadius: 12, background: '#000' }}></video></div>}
        {permError && <div style={{ padding: 12, background: 'rgba(220,38,38,0.08)', borderRadius: 8, color: 'var(--danger)', fontSize: '0.85rem', marginBottom: 16 }}>{permError}</div>}
        {!camOk ? (
          <button className="btn btn-primary btn-lg" onClick={requestPermissions}>🔓 Grant Access</button>
        ) : (
          <button className="btn btn-success btn-lg" onClick={enterRoom}>🚀 Enter Viva Room</button>
        )}
      </div>
    );
  }

  // Room phase
  return (
    <div className="viva-dark fade-up">
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
        <div>
          <span className="badge badge-success">🟢 Connected</span>
          <span style={{ marginLeft: 12, fontWeight: 600, color: '#fff' }}>{session ? session.title : 'Viva Session'}</span>
        </div>
      </div>
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16, maxWidth: 800, margin: '0 auto' }}>
        <div className="card" style={{ padding: 12 }}>
          <video ref={selfVidRef} autoPlay muted playsInline style={{ width: '100%', borderRadius: 8, background: '#000', minHeight: 200 }}></video>
          <div style={{ textAlign: 'center', marginTop: 8, fontSize: '0.85rem', color: '#9ca3af' }}>You</div>
          <div style={{ display: 'flex', gap: 8, justifyContent: 'center', marginTop: 8 }}>
            <button className={'btn btn-sm ' + (camOn ? 'btn-success' : 'btn-danger')} onClick={toggleCam}>{camOn ? '📷 Camera On' : '📷 Camera Off'}</button>
            <button className={'btn btn-sm ' + (micOn ? 'btn-success' : 'btn-danger')} onClick={toggleMic}>{micOn ? '🎤 Mic On' : '🎤 Mic Off'}</button>
          </div>
        </div>
        <div className="card" style={{ padding: 12, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
          <div style={{ textAlign: 'center', color: '#9ca3af' }}>
            <div style={{ fontSize: '3rem', marginBottom: 8 }}>👨‍🏫</div>
            <div>Examiner View</div>
            <div style={{ fontSize: '0.75rem', marginTop: 4 }}>Waiting for examiner...</div>
          </div>
        </div>
      </div>
    </div>
  );
}
